prepare:
New-Item -ItemType Directory -Force 'C:\lab\mgnet' | Out-Null; $env:MG_LOGS = 'C:\lab\mgnet'; $env:MG_SVC = Join-Path $env:MG_LOGS 'svc.ps1'; Set-Content -LiteralPath $env:MG_SVC -Value @'
param([Parameter(Mandatory)][ValidateSet('start','ensure','stop')][string]$Action, [Parameter(Mandatory)][string]$Name, [string]$Project, [string]$Urls, [int]$Port, [string[]]$AppArgs = @(), [string[]]$DeleteFiles = @())
$d = 'C:\lab\mgnet'; New-Item -ItemType Directory -Force $d | Out-Null
$pf = Join-Path $d "$Name.pid"
function Test-Port([int]$p) { try { [Net.Sockets.TcpClient]::new('localhost', $p).Dispose(); $true } catch { $false } }
function Stop-Svc { if (Test-Path $pf) { taskkill /PID (Get-Content $pf) /T /F 2>&1 | Out-Null; Remove-Item $pf -ErrorAction SilentlyContinue } }
if ($Action -eq 'stop') { Stop-Svc; return }
if ($Action -eq 'ensure' -and $Port -and (Test-Port $Port)) { return }
Stop-Svc
foreach ($f in $DeleteFiles) { Remove-Item (Join-Path $Project $f) -Force -ErrorAction SilentlyContinue }
$env:ASPNETCORE_ENVIRONMENT = 'Development'
$a = @('run', '--no-build', '--no-launch-profile')
if ($Urls) { $a += '--urls', $Urls }
if ($AppArgs) { $a += '--'; $a += $AppArgs }
$p = Start-Process dotnet -ArgumentList $a -WorkingDirectory $Project -WindowStyle Hidden -RedirectStandardOutput (Join-Path $d "$Name.log") -RedirectStandardError (Join-Path $d "$Name.err") -PassThru
$p.Id | Set-Content $pf
if ($Port) { for ($i = 0; $i -lt 120; $i++) { if (Test-Port $Port) { break }; Start-Sleep -Milliseconds 500 } }
'@

